"""Embed timeline and create a standalone offline audio-and-text reader."""
import html
import json
import shutil
from pathlib import Path

ROOT = Path(__file__).resolve().parent

def main():
    timeline = json.loads((ROOT/'output/timeline.json').read_text(encoding='utf-8'))
    clips = timeline['segments']
    if not clips or not (ROOT/'output/story.mp3').is_file(): raise ValueError('缺少时间轴或音频')
    images = ROOT/'output/images'; images.mkdir(parents=True,exist_ok=True)
    for i in range(1,5): shutil.copy2(ROOT.parent/f'week3_picturebook/images/scene-{i:02}.png', images/f'scene-{i:02}.png')
    data = json.dumps(timeline, ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
    title = html.escape(timeline['title'])
    doc = '''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>__TITLE__ · 星梦有声故事</title><style>
    *{box-sizing:border-box}body{margin:0;color:#29483b;background:#f8f7ef;font-family:"Microsoft YaHei",sans-serif}header{max-width:1120px;margin:auto;padding:24px 20px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #e1e6d8}header b{font-family:Georgia,serif;font-size:20px}header span{font:10px Arial;letter-spacing:2px;color:#899683}.wrap{max-width:1120px;margin:auto;padding:38px 20px 80px}.intro{display:grid;grid-template-columns:1fr 1fr;gap:45px;align-items:center}.intro img{width:100%;border-radius:48% 48% 16px 16px;aspect-ratio:1.45;object-fit:cover}.kicker{color:#a58c5e;font:10px Arial;letter-spacing:2px}h1{font:700 clamp(30px,4vw,46px)/1.4 Georgia,"Songti SC",serif;margin:20px 0}.intro p{color:#778a75;line-height:2}.player{position:sticky;top:0;z-index:2;background:#fffef8;border:1px solid #e2e7d9;border-radius:16px;padding:16px 20px;margin:32px 0;box-shadow:0 7px 30px #36553712}.player p{margin:0 0 8px;color:#607b5f;font-size:13px}audio{display:block;width:100%;height:40px}.hint{font-size:12px;color:#84917b}.scene{display:grid;grid-template-columns:220px 1fr;gap:30px;margin:35px 0;padding:28px;background:#fffefa;border:1px solid #e4e9dc;border-radius:20px;align-items:start}.scene>img{width:100%;border-radius:14px;position:sticky;top:105px}.scene h2{font:700 22px Georgia,serif;margin:0 0 16px}.line{display:flex;gap:14px;width:100%;text-align:left;border:1px solid transparent;background:transparent;border-radius:10px;padding:13px 12px;cursor:pointer;color:#596f5e;font:15px/1.9 Georgia,"Songti SC",serif}.line:hover{background:#f4f6ed}.line.active{background:#e6efdf;border-color:#abc3a2;color:#294c38}.line:focus-visible{outline:3px solid #b98637;outline-offset:2px}.role{flex:0 0 66px;font:12px/2 "Microsoft YaHei",sans-serif;color:#839777}.role strong{display:block;color:#517252}.meta{font-size:11px;color:#9aa993}.end{text-align:center;color:#82917c;padding:30px}.empty{color:#89988b}@media(max-width:700px){header span{display:none}.wrap{padding:25px 15px 45px}.intro{grid-template-columns:1fr;gap:14px}.intro img{height:230px}.player{padding:13px;margin:22px 0}.scene{display:block;padding:18px;margin:18px 0}.scene>img{position:static;height:180px;object-fit:cover}.scene h2{margin-top:20px}.line{font-size:14px;gap:8px;padding:11px 5px}.role{flex-basis:52px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}
    </style></head><body><header><b>✦ 星梦有声故事</b><span>LISTEN TO A LITTLE WONDER</span></header><main class="wrap"><section class="intro"><div><span class="kicker">A STORY ABOUT FRIENDSHIP</span><h1>__TITLE__</h1><p>戴上耳机，和小月、小狐狸栗栗一起，<br>去森林里找回风铃树的歌声。</p><span class="hint">四幕故事 · 三位角色与旁白 · 点击台词跳转</span></div><img src="images/scene-01.png" alt="小月与小狐狸走进萤光森林"></section><div class="player"><p id="now" aria-live="polite">准备好了吗？点击播放开始故事。</p><audio id="audio" controls preload="metadata" src="story.mp3">当前浏览器无法播放音频，请打开 story.mp3。</audio><div class="hint">播放时文字自动高亮；点击任意一句可跳到对应位置。</div></div><div id="scenes"></div><div class="end">✦ 好奇、细心和陪伴，让每个小小的办法都闪闪发光。</div></main><script type="application/json" id="story-data">__DATA__</script><script>
    const data=JSON.parse(document.querySelector('#story-data').textContent),audio=document.querySelector('#audio'),container=document.querySelector('#scenes'),now=document.querySelector('#now');let previous=-1;
    const names=['','相遇与出发','溪边的新朋友','找回铃声','风中的晚安'];
    for(let s=1;s<=4;s++){const section=document.createElement('section');section.className='scene';const img=document.createElement('img');img.src=`images/scene-0${s}.png`;img.alt=names[s]+'场景插画';section.append(img);const content=document.createElement('div');const title=document.createElement('h2');title.textContent=`0${s} / ${names[s]}`;content.append(title);data.segments.forEach((seg,i)=>{if(seg.scene!==s)return;const btn=document.createElement('button');btn.className='line';btn.type='button';btn.dataset.index=i;const role=document.createElement('span');role.className='role';const strong=document.createElement('strong');strong.textContent=seg.role;const mood=document.createElement('span');mood.className='meta';mood.textContent=seg.emotion;role.append(strong,mood);const words=document.createElement('span');words.textContent=seg.text;btn.append(role,words);btn.addEventListener('click',()=>{audio.currentTime=seg.start;audio.play().catch(()=>{now.textContent='暂时无法播放，请使用浏览器音频控件重试。';});update();});content.append(btn)});section.append(content);container.append(section)}
    const lines=Array.from(document.querySelectorAll('.line'));function update(){const t=audio.currentTime;let i=data.segments.findIndex(s=>t>=s.start&&t<s.end);if(i<0)i=data.segments.findIndex((s,j)=>t>=s.end&&j+1<data.segments.length&&t<data.segments[j+1].start);if(i===previous)return;if(previous>=0){lines[previous].classList.remove('active');lines[previous].removeAttribute('aria-current')}previous=i;if(i>=0){lines[i].classList.add('active');lines[i].setAttribute('aria-current','true');now.textContent=`正在讲述：${data.segments[i].role} · ${data.segments[i].emotion}`;}}audio.addEventListener('timeupdate',update);audio.addEventListener('seeked',update);audio.addEventListener('error',()=>now.textContent='音频无法加载，请检查 story.mp3 是否与本页面放在一起。');
    </script></body></html>'''.replace('__TITLE__',title).replace('__DATA__',data)
    (ROOT/'output/index.html').write_text(doc,encoding='utf-8')
    print('同步阅读页面已生成：output/index.html')

if __name__ == '__main__':
    try: main()
    except (OSError,ValueError,KeyError) as exc: raise SystemExit(f'生成失败：{exc}')
